(function(root){
  'use strict';
  const W=13,H=8,N=W*H,MAX=200;
  const blank=()=>({pixels:Array(N).fill(0),duration:250});
  function validate(raw){
    if(!raw||raw.version!==1||!['gray','binary'].includes(raw.mode)||typeof raw.loop!=='boolean'||![.5,1,2,4].includes(raw.speed)||!Array.isArray(raw.frames)||raw.frames.length<1||raw.frames.length>MAX)throw Error('지원하지 않는 프로젝트 형식입니다.');
    const frames=raw.frames.map(f=>{if(!f||!Array.isArray(f.pixels)||f.pixels.length!==N||f.pixels.some(v=>!Number.isInteger(v)||v<0||v>7)||(raw.mode==='binary'&&f.pixels.some(v=>v!==0&&v!==7))||!Number.isInteger(f.duration)||f.duration<20||f.duration>60000)throw Error('프레임 데이터 또는 표시 시간이 올바르지 않습니다.');return {pixels:[...f.pixels],duration:f.duration};});
    return {version:1,mode:raw.mode,loop:raw.loop,speed:raw.speed,frames};
  }
  function flip(p,vertical){return p.map((_,i)=>p[vertical?(H-1-Math.floor(i/W))*W+i%W:Math.floor(i/W)*W+W-1-i%W]);}
  function quantize(rgba,mode,threshold,invert){return Array.from({length:N},(_,i)=>{let a=rgba[i*4+3]/255;if(a===0)return 0;let v=.2126*rgba[i*4]+.7152*rgba[i*4+1]+.0722*rgba[i*4+2];if(invert)v=255-v;v=Math.round(v*a);return mode==='binary'?(v>=threshold?7:0):Math.max(0,Math.min(7,Math.round(v/255*7)));});}
  function generate(raw){const p=validate(raw),bit=p.mode==='binary'?1:3;const data=p.frames.map((f,i)=>'  { // Frame '+(i+1)+'\n'+Array.from({length:H},(_,y)=>'    '+f.pixels.slice(y*W,(y+1)*W).map(v=>bit===1?(v?1:0):v).join(', ')).join(',\n')+'\n  }').join(',\n');const times=p.frames.map(f=>Math.max(1,Math.round(f.duration/p.speed))+'UL').join(', ');return `// Arduino UNO Q - 13 columns x 8 rows\n// Paste into Arduino App Lab: sketch/sketch.ino\n#include <Arduino_LED_Matrix.h>\n\nArduino_LED_Matrix matrix;\nconstexpr uint16_t FRAME_COUNT = ${p.frames.length};\nconstexpr bool REPEAT = ${p.loop};\n\n// Left to right, top to bottom. Brightness: 0..${bit===1?1:7}.\nuint8_t frames[FRAME_COUNT][104] = {\n${data}\n};\nconst unsigned long durations[FRAME_COUNT] = { ${times} };\n\nuint16_t currentFrame = 0;\nunsigned long frameStartedAt = 0;\nbool finished = false;\n\nvoid setup() {\n  matrix.begin();\n  matrix.setGrayscaleBits(${bit});\n  matrix.draw(frames[0]);\n  frameStartedAt = millis();\n}\n\nvoid loop() {\n  if (finished) return;\n  const unsigned long now = millis();\n  if (now - frameStartedAt < durations[currentFrame]) return;\n\n  if (currentFrame + 1 < FRAME_COUNT) {\n    ++currentFrame;\n  } else if (REPEAT) {\n    currentFrame = 0;\n  } else {\n    finished = true;\n    return; // Keep the last frame visible.\n  }\n  matrix.draw(frames[currentFrame]);\n  frameStartedAt = now;\n}\n`;}
  const api={W,H,N,MAX,blank,validate,flip,quantize,generate};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.LedCore=api;
})(globalThis);
